    institutions:[['产业培育','首页.html'],['培训课程','培训课程.html'],['培训机构']],
    learning:[['产业培育','首页.html'],['我的培训考试','我的培训考试.html'],['我的培训','我的培训.html'],['在线课程学习']],
    'my-orders':[['产业培育','首页.html'],['培训课程','培训课程.html'],['我的订单']],
    'my-training':[['产业培育','首页.html'],['我的培训考试','我的培训考试.html'],['我的培训']],
