  if(page==='my-center'){const requestedRole=new URLSearchParams(location.search).get('role');if(['personal','team'].includes(requestedRole))localStorage.setItem('trainingZone.role',requestedRole);const requested=location.hash.slice(1);centerView=centerLabels[requested]?requested:'overview';if(centerView==='teams'&&getCenterRole()!=='team')centerView='overview';renderCenterRole();switchCenterPanel(centerView,false)}
  const account=$('#prototype-account');if(account){const role=localStorage.getItem('trainingZone.role')||'visitor';account.textContent=role==='visitor'?'登录/注册':role==='team'?'王工（团队）':'张明（个人）'}
