  if(page==='training-record'){const heroAction=document.querySelector('.detail-hero>.proto-button');if(heroAction){const note=document.createElement('p');note.className='send-exam-note';note.textContent='培训完成后由培训机构按流程统一送考，考试安排请在“考试计划-考试安排”或“我的培训考试-业务总览”中查看';heroAction.replaceWith(note)}document.querySelector('.training-record-grid')?.classList.add('training-record-grid');const grid=document.querySelector('.detail-grid');if(grid){grid.classList.add('training-record-grid');grid.querySelector('.side-stack')?.remove();grid.querySelector(':scope>section')?.classList.add('training-record-main')}}
  if(page==='exam-schedule'){document.querySelector('.detail-hero-meta>span:nth-child(2)')?.remove();document.querySelector('.page-heading p')?.remove();document.querySelectorAll('.detail-grid .alert').forEach(alert=>alert.remove());const theory=document.querySelector('.detail-grid>section .content-section:first-child .info-grid');if(theory){const login=theory.children[2],entry=theory.children[3];if(login){login.querySelector('span').textContent='考场';login.querySelector('strong').textContent='A01'}if(entry){entry.querySelector('span').textContent='考场地址';entry.querySelector('strong').textContent='滨海路湖北智能建造评价基地337号'}}const practicalSection=document.querySelector('.detail-grid>section .content-section:nth-child(2)');const practical=practicalSection?.querySelector('.info-grid');if(practicalSection)practicalSection.querySelector('h2').textContent='实操考试';if(practical){const place=practical.children[1],room=practical.children[2],roomAddress=practical.children[3];if(place){place.querySelector('span').textContent='考试方式';place.querySelector('strong').textContent='线下实操'}if(room){room.querySelector('span').textContent='考场';room.querySelector('strong').textContent='A01'}if(roomAddress){roomAddress.querySelector('span').textContent='考场地址';roomAddress.querySelector('strong').textContent='滨海路湖北智能建造评价基地337号'}}const timeline=document.querySelector('.side-stack .timeline');if(timeline){timeline.children[0]?.querySelector('strong')&&(timeline.children[0].querySelector('strong').textContent='培训机构已送考');timeline.children[1]?.querySelector('strong')&&(timeline.children[1].querySelector('strong').textContent='评价机构已安排考试')}}
  if(page==='score'){document.querySelector('.page-heading p')?.remove();const hero=document.querySelector('.score-hero');if(hero){hero.querySelector('p').textContent='考试批次 EXA202611150128 · 考试日期 2026-12-08';hero.querySelectorAll('.status-tag').forEach(tag=>tag.remove())}document.querySelector('.score-grid')?.remove();const grid=document.querySelector('.detail-grid');if(grid){grid.classList.add('score-detail-grid');grid.querySelector('.side-stack')?.remove()}const surface=document.querySelector('.detail-grid>section.surface');if(surface){surface.querySelector('.content-section:nth-child(2)')?.remove();const table=surface.querySelector('.content-section table');if(table){table.querySelectorAll('tr').forEach(row=>{row.children[4]?.remove();row.children[3]?.remove()});const meta=document.createElement('div');meta.className='score-publish-meta';meta.innerHTML='<p><span>发布机构：</span>湖北绿色建造职业技能评价中心</p><p><span>发布时间：</span>2026-12-13 09:00</p>';table.parentNode.appendChild(meta)}}}
